-- ── W9 안녕? 봄아! · 성장키워드 웃음
do $load$
declare
  v_status text;
  v_body text;
  v_body_json jsonb;
  v_expected text;
  v_expected_json jsonb;
begin
  select status into v_status from public.curriculum_lessons where id = 'e72c0e9d-c050-35df-8835-36104959c8c9';
  if not found then
    insert into public.curriculum_lessons (id, program_id, week_no, session_no, title, objective, duration_minutes, status)
    values ('e72c0e9d-c050-35df-8835-36104959c8c9', '9e5a1823-7344-3020-86dc-0f0c35247fe7', 9, 1, $t$안녕? 봄아!$t$, $t$봄의 마지막까지 신나게 즐겨요.$t$, null, 'draft');
    v_status := 'draft';
  end if;

  v_expected := $b$9주차의 목표는 아이들에게 봄의 특징이나 계절의 순서를 지식으로 설명하는 것이 아닙니다. 아이들이 꽃잎의 색과 움직임을 보고, 만지고, 몸으로 꽃비를 경험한 뒤 ‘어? 전에는 꽃이 많았는데 지금은 초록색이 많아졌네?’라는 계절의 변화를 스스로 발견하도록 돕는 것이 핵심입니다.

수업의 경험 구조
늦봄의 숲 만나기 → 꽃눈의 움직임 발견 → 꽃비를 몸으로 경험하기 → 봄꽃을 다시 표현하기 → 초록빛으로 변한 숲 발견 → 꽃다발로 봄의 기억 남기기

교사의 역할
• ‘봄이 끝났어요’라고 먼저 설명하기보다 아이들이 꽃과 잎의 변화를 직접 발견하도록 질문합니다.
• 꽃비 놀이는 예쁜 장면을 연출하는 것보다 아이들이 꽃잎을 모으고, 날리고, 맞고, 웃는 놀이 과정 자체를 충분히 경험하게 합니다.
• 꽃 이름을 많이 맞히게 하기보다 색·모양·움직임·느낌을 자유롭게 표현하게 합니다.
• ‘꽃이 없어져서 슬프지?’처럼 감정을 정해주지 않고 아쉬움·신남·궁금함 등 아이마다 다른 반응을 인정합니다.
• 가정연계의 의미를 수업 중 미리 설명하거나 ‘엄마에게 꼭 줘야 해’라고 관계교육으로 연결하지 않습니다.$b$;
  v_expected_json := $j${"blockKey":"beforeStart","value":{"intro":"9주차의 목표는 아이들에게 봄의 특징이나 계절의 순서를 지식으로 설명하는 것이 아닙니다. 아이들이 꽃잎의 색과 움직임을 보고, 만지고, 몸으로 꽃비를 경험한 뒤 ‘어? 전에는 꽃이 많았는데 지금은 초록색이 많아졌네?’라는 계절의 변화를 스스로 발견하도록 돕는 것이 핵심입니다.","experienceFlow":["늦봄의 숲 만나기","꽃눈의 움직임 발견","꽃비를 몸으로 경험하기","봄꽃을 다시 표현하기","초록빛으로 변한 숲 발견","꽃다발로 봄의 기억 남기기"],"teacherRoles":["‘봄이 끝났어요’라고 먼저 설명하기보다 아이들이 꽃과 잎의 변화를 직접 발견하도록 질문합니다.","꽃비 놀이는 예쁜 장면을 연출하는 것보다 아이들이 꽃잎을 모으고, 날리고, 맞고, 웃는 놀이 과정 자체를 충분히 경험하게 합니다.","꽃 이름을 많이 맞히게 하기보다 색·모양·움직임·느낌을 자유롭게 표현하게 합니다.","‘꽃이 없어져서 슬프지?’처럼 감정을 정해주지 않고 아쉬움·신남·궁금함 등 아이마다 다른 반응을 인정합니다.","가정연계의 의미를 수업 중 미리 설명하거나 ‘엄마에게 꼭 줘야 해’라고 관계교육으로 연결하지 않습니다."]}}$j$::jsonb;
  select body, body_json into v_body, v_body_json from public.lesson_sections
  where lesson_id = 'e72c0e9d-c050-35df-8835-36104959c8c9' and section_code = $t$s1$t$;
  if not found then
    if v_status <> 'draft' then
      raise exception 'W9 게시된 차시에 s1 가 없다 — 새 버전으로 적재해야 한다';
    end if;
    insert into public.lesson_sections (lesson_id, section_code, body, body_json, source_ref)
    values ('e72c0e9d-c050-35df-8835-36104959c8c9', $t$s1$t$, v_expected, v_expected_json, $t$SOYES_KIDS_9주차_교사용_수업가이드.pdf §s1 (sha256:7c4394c2587c1ff5) · TAP24 2026.1$t$);
  elsif v_body is distinct from v_expected or v_body_json is distinct from v_expected_json then
    if v_status <> 'draft' then
      raise exception 'W9 s1 게시본과 전사본이 다르다 — 게시본은 조용히 고치지 않는다 (DEC-096)';
    end if;
    update public.lesson_sections set body = v_expected, body_json = v_expected_json, source_ref = $t$SOYES_KIDS_9주차_교사용_수업가이드.pdf §s1 (sha256:7c4394c2587c1ff5) · TAP24 2026.1$t$
    where lesson_id = 'e72c0e9d-c050-35df-8835-36104959c8c9' and section_code = $t$s1$t$;
  end if;

  v_expected := $b$주제 — 안녕? 봄아! · 봄의 끝자락
그림책 — 《안녕? 봄아!》
성장키워드 — 웃음
핵심 메시지 — 봄의 마지막까지 신나게 즐겨요.
핵심 활동 — 그림책 → 꽃과 숲의 변화 발견 → 꽃비가 내려요! → 워크북 → 나만의 꽃다발 → 마무리 → 가정연계
