  elsif v_body is distinct from v_expected or v_body_json is distinct from v_expected_json then
    if v_status <> 'draft' then
      raise exception 'W10 s15 게시본과 전사본이 다르다 — 게시본은 조용히 고치지 않는다 (DEC-096)';
    end if;
    update public.lesson_sections set body = v_expected, body_json = v_expected_json, source_ref = $t$SOYES_KIDS_10주차_교사용_수업가이드 (1).pdf §s15 (sha256:dcfddb5d6e2a19ab) · TAP24 2026.1$t$
