    end if;
    insert into public.lesson_sections (lesson_id, section_code, body, body_json, source_ref)
    values ('5625986a-c880-3205-8f5a-e2eeb00a029e', $t$s15$t$, v_expected, v_expected_json, $t$SOYES_KIDS_12주차_교사용_수업가이드.pdf §s15 (sha256:02729998b203d6d0) · TAP24 2026.1$t$);
  elsif v_body is distinct from v_expected or v_body_json is distinct from v_expected_json then
    if v_status <> 'draft' then
      raise exception 'W12 s15 게시본과 전사본이 다르다 — 게시본은 조용히 고치지 않는다 (DEC-096)';
    end if;
    update public.lesson_sections set body = v_expected, body_json = v_expected_json, source_ref = $t$SOYES_KIDS_12주차_교사용_수업가이드.pdf §s15 (sha256:02729998b203d6d0) · TAP24 2026.1$t$
